1	package credit
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9	)
10	
11	// recordVersion 是当前记录文件格式版本。
12	const recordVersion = 1
13	
14	// fileData 是记录文件的磁盘格式。
15	type fileData struct {
16		Version       int            `json:"version"`
17		Courses       []*Course      `json:"courses"`
18		Students      []*Student     `json:"students"`
19		Requirements  []*Requirement `json:"requirements"`
20		Enrollments   []*Enrollment  `json:"enrollments"`
21		Waivers       []*Waiver      `json:"waivers"`
22		NextResultSeq int            `json:"nextResultSeq"`
23	}
24	
25	// Load 从 path 读取记录。
26	//
27	// 文件不存在时返回空记录集，existed=false，且不报错——即“从空记录开始”。
28	// 文件存在但无法读取（权限、I/O 错误等）或内容损坏（非法 JSON、结构矛盾、
29	// 引用悬空等）时返回错误，调用方绝不应把该文件当作空记录覆盖写入。
30	// 空文件同样视为损坏，而不是空记录。
31	func Load(path string) (s *Store, existed bool, err error) {
32		f, err := os.Open(path)
33		if err != nil {
34			if errors.Is(err, os.ErrNotExist) {
35				return NewStore(), false, nil
36			}
37			return nil, false, fmt.Errorf("无法读取记录文件 %s：%w", path, err)
38		}
39		defer f.Close()
40	
41		fi, err := f.Stat()
42		if err != nil {
43			return nil, false, fmt.Errorf("无法读取记录文件 %s 的信息：%w", path, err)
44		}
45		if fi.Size() == 0 {
46			return nil, true, fmt.Errorf("记录文件 %s 存在但为空，内容已损坏，未做任何修改", path)
47		}
48	
49		var data fileData
50		dec := json.NewDecoder(f)
51		dec.DisallowUnknownFields()
52		if err := dec.Decode(&data); err != nil {
53			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（JSON 解析失败：%v），未做任何修改", path, err)
54		}
55		// 不允许同一文件中拼接多段 JSON。
56		if dec.More() {
57			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（含有多余数据），未做任何修改", path)
58		}
59	
60		s = NewStore()
61		if err := s.loadData(&data); err != nil {
62			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（%v），未做任何修改", path, err)
63		}
64		return s, true, nil
65	}
66	
67	// loadData 校验磁盘数据并重建索引；任何矛盾都作为损坏报错。
68	func (s *Store) loadData(d *fileData) error {
69		if d.Version != recordVersion {
70			return fmt.Errorf("不支持的记录版本 %d（当前支持版本 %d）", d.Version, recordVersion)
71		}
72	
73		// 课程
74		for _, c := range d.Courses {
75			if c == nil {
76				return errors.New("存在空的课程记录")
77			}
78			if c.ID == "" {
79				return errors.New("存在没有编号的课程")
80			}
81			if c.Name == "" {
82				return fmt.Errorf("课程 %s 没有名称", c.ID)
83			}
84			if c.Credit <= 0 {
85				return fmt.Errorf("课程 %s 学分不是正整数：%d", c.ID, c.Credit)
86			}
87			if _, dup := s.courseByID[c.ID]; dup {
88				return fmt.Errorf("课程编号 %s 重复", c.ID)
89			}
90			s.courses = append(s.courses, c)
91			s.courseByID[c.ID] = c
92		}
93	
94		// 学生
95		for _, st := range d.Students {
96			if st == nil || st.ID == "" {
97				return errors.New("存在没有编号的学生记录")
98			}
99			if _, dup := s.studentByID[st.ID]; dup {
100				return fmt.Errorf("学生编号 %s 重复", st.ID)
101			}
102			s.students = append(s.students, st)
103			s.studentByID[st.ID] = st
104		}
105	
106		// 要求
107		for _, r := range d.Requirements {
108			if r == nil {
109				return errors.New("存在空的课程要求记录")
110			}
111			if r.StudentID == "" || r.ID == "" {
112				return errors.New("存在缺少学生编号或要求编号的课程要求")
113			}
114			if _, ok := s.studentByID[r.StudentID]; !ok {
115				return fmt.Errorf("要求 %s 引用了不存在的学生 %s", r.ID, r.StudentID)
116			}
117			if _, ok := s.courseByID[r.CourseID]; !ok {
118				return fmt.Errorf("学生 %s 的要求 %s 引用了不存在的课程 %s",
119					r.StudentID, r.ID, r.CourseID)
120			}
121			key := reqKey(r.StudentID, r.ID)
122			if _, dup := s.reqByKey[key]; dup {
123				return fmt.Errorf("学生 %s 的要求编号 %s 重复", r.StudentID, r.ID)
124			}
125			dk := dupKey(r.StudentID, r.CourseID)
126			if other, dup := s.reqByDup[dk]; dup {
127				return fmt.Errorf("学生 %s 就课程 %s 存在重复要求 %s 与 %s",
128					r.StudentID, r.CourseID, other, r.ID)
129			}
130			s.requirements = append(s.requirements, r)
131			s.reqByKey[key] = r
132			s.reqByDup[dk] = r.ID
133		}
134	
135		// 修读
136		usedSeq := map[int]bool{}
137		for _, e := range d.Enrollments {
138			if e == nil {
139				return errors.New("存在空的修读记录")
140			}
141			if e.StudentID == "" || e.ID == "" {
142				return errors.New("存在缺少学生编号或修读编号的修读记录")
143			}
144			if _, ok := s.studentByID[e.StudentID]; !ok {
145				return fmt.Errorf("修读 %s 引用了不存在的学生 %s", e.ID, e.StudentID)
146			}
147			r := s.reqByKey[reqKey(e.StudentID, e.ReqID)]
148			if r == nil {
149				return fmt.Errorf("学生 %s 的修读 %s 引用了不存在的要求 %s",
150					e.StudentID, e.ID, e.ReqID)
151			}
152			if e.Term == "" {
153				return fmt.Errorf("学生 %s 的修读 %s 缺少学期", e.StudentID, e.ID)
154			}
155			switch e.Result {
156			case Enrolled, Passed, Failed:
157			default:
158				return fmt.Errorf("学生 %s 的修读 %s 含非法结果 %q", e.StudentID, e.ID, e.Result)
159			}
160			if e.Result == Enrolled {
161				if e.ResultSeq != 0 {
162					return fmt.Errorf("修读 %s 尚未提交结果却带有结果序号", e.ID)
163				}
164			} else {
165				if e.ResultSeq <= 0 {
166					return fmt.Errorf("修读 %s 已提交结果但缺少结果序号", e.ID)
167				}
168				if usedSeq[e.ResultSeq] {
169					return fmt.Errorf("结果提交序号 %d 重复，记录已损坏", e.ResultSeq)
170				}
171				usedSeq[e.ResultSeq] = true
172			}
173			key := reqKey(e.StudentID, e.ID)
174			if _, dup := s.enrByKey[key]; dup {
175				return fmt.Errorf("学生 %s 的修读编号 %s 重复", e.StudentID, e.ID)
176			}
177			s.enrollments = append(s.enrollments, e)
178			s.enrByKey[key] = e
179		}
180	
181		// 免修（被拒绝的申请允许指向当时不存在的要求）
182		approvedReq := map[string]string{} // student+"\x00"+req -> waiverID
183		for _, w := range d.Waivers {
184			if w == nil {
185				return errors.New("存在空的免修记录")
186			}
187			if w.StudentID == "" || w.ID == "" {
188				return errors.New("存在缺少学生编号或免修编号的免修记录")
189			}
190			if _, ok := s.studentByID[w.StudentID]; !ok {
191				return fmt.Errorf("免修 %s 引用了不存在的学生 %s", w.ID, w.StudentID)
192			}
193			switch w.Status {
194			case WaiverApproved, WaiverRejected, WaiverRevoked:
195			default:
196				return fmt.Errorf("学生 %s 的免修 %s 含非法状态 %q", w.StudentID, w.ID, w.Status)
197			}
198			if w.Status == WaiverApproved {
199				if w.Basis == "" {
200					return fmt.Errorf("有效免修 %s 缺少依据", w.ID)
201				}
202				rk := reqKey(w.StudentID, w.ReqID)
203				if s.reqByKey[rk] == nil {
204					return fmt.Errorf("有效免修 %s 指向不存在的要求 %s", w.ID, w.ReqID)
205				}
206				if other, dup := approvedReq[rk]; dup {
207					return fmt.Errorf("学生 %s 的要求 %s 同时存在有效免修 %s 与 %s",
208						w.StudentID, w.ReqID, other, w.ID)
209				}
210				approvedReq[rk] = w.ID
211			}
212			key := reqKey(w.StudentID, w.ID)
213			if _, dup := s.waiverByKey[key]; dup {
214				return fmt.Errorf("学生 %s 的免修编号 %s 重复", w.StudentID, w.ID)
215			}
216			s.waivers = append(s.waivers, w)
217			s.waiverByKey[key] = w
218		}
219	
220		if d.NextResultSeq < 0 {
221			return errors.New("结果提交序号计数器为负数")
222		}
223		for seq := range usedSeq {
224			if seq > d.NextResultSeq {
225				return fmt.Errorf("结果提交序号计数器 %d 小于已有序号 %d", d.NextResultSeq, seq)
226			}
227		}
228		s.nextResultSeq = d.NextResultSeq
229		return nil
230	}
231	
232	// Save 将全部记录原子写入 path：先写同目录临时文件，再重命名覆盖，
233	// 避免写到一半时损坏原文件。
234	func (s *Store) Save(path string) (err error) {
235		data := fileData{
236			Version:       recordVersion,
237			Courses:       s.courses,
238			Students:      s.students,
239			Requirements:  s.requirements,
240			Enrollments:   s.enrollments,
241			Waivers:       s.waivers,
242			NextResultSeq: s.nextResultSeq,
243		}
244		buf, err := json.MarshalIndent(&data, "", "  ")
245		if err != nil {
246			return fmt.Errorf("无法序列化记录：%w", err)
247		}
248		buf = append(buf, '\n')
249	
250		dir := filepath.Dir(path)
251		if dir == "" {
252			dir = "."
253		}
254		tmp, err := os.CreateTemp(dir, ".credit-*.tmp")
255		if err != nil {
256			return fmt.Errorf("无法在 %s 创建临时记录文件：%w", dir, err)
257		}
258		tmpName := tmp.Name()
259		defer func() {
260			if err != nil {
261				tmp.Close()
262				os.Remove(tmpName)
263			}
264		}()
265		if _, err = tmp.Write(buf); err != nil {
266			return fmt.Errorf("写入记录文件失败：%w", err)
267		}
268		if err = tmp.Sync(); err != nil {
269			return fmt.Errorf("写入记录文件失败：%w", err)
270		}
271		if err = tmp.Close(); err != nil {
272			return fmt.Errorf("写入记录文件失败：%w", err)
273		}
274		if err = os.Chmod(tmpName, 0o600); err != nil {
275			return fmt.Errorf("设置记录文件权限失败：%w", err)
276		}
277		if err = os.Rename(tmpName, path); err != nil {
278			return fmt.Errorf("保存记录文件 %s 失败：%w", path, err)
279		}
280		return nil
281	}
