1	// credit 是本地课程学分与免修的命令行程序。
2	//
3	// 用法：credit -f 记录文件 <子命令> [参数...]
4	//
5	// 学生与课程：
6	//
7	//	student <编号>                              登记学生（编号唯一）
8	//	course <编号> <名称...> <正整数学分>          登记课程（初始开放）
9	//	course-close <编号>                          停开课程
10	//	course-open <编号>                           恢复开放课程
11	//	list-courses                                列出全部课程及状态
12	//
13	// 课程要求（编号在学生名下唯一）：
14	//
15	//	req <学生> <要求编号> <课程编号>              为学生登记课程要求
16	//
17	// 修读（编号在学生名下唯一）：
18	//
19	//	enroll <学生> <要求编号> <学期> <修读编号>    选课登记
20	//	pass   <学生> <修读编号>                      提交“通过”
21	//	fail   <学生> <修读编号>                      提交“未通过”
22	//
23	// 免修（编号在学生名下唯一）：
24	//
25	//	waiver        <学生> <要求编号> <免修编号> <依据...>  提交免修申请
26	//	revoke-waiver <学生> <免修编号> [原因...]            撤销有效免修
27	//
28	// 核对与查询：
29	//
30	//	check <学生>                                 按学生核对学分
31	//	show  <学生>                                 查看学生的要求、修读与免修历史
32	//
33	// 记录文件不存在时从空记录开始；文件无法读取或内容损坏时立即报错，
34	// 不会把它当作空记录覆盖。
35	package main
36	
37	import (
38		"errors"
39		"flag"
40		"fmt"
41		"io"
42		"os"
43		"strconv"
44		"strings"
45	
46		"github.com/descikazuyq/credit-record/credit"
47	)
48	
49	// 退出码：0 成功；1 业务规则被拒绝；2 记录文件错误。
50	const (
51		exitOK       = 0
52		exitRejected = 1
53		exitFile     = 2
54	)
55	
56	func main() {
57		os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
58	}
59	
60	func run(args []string, stdout, stderr io.Writer) int {
61		fs := flag.NewFlagSet("credit", flag.ContinueOnError)
62		fs.SetOutput(stderr)
63		fs.Usage = func() {
64			fmt.Fprintln(stderr, "用法：credit -f 记录文件 <子命令> [参数...]")
65			fmt.Fprintln(stderr, "子命令：student course course-close course-open list-courses")
66			fmt.Fprintln(stderr, "        req enroll pass fail waiver revoke-waiver check show")
67			fmt.Fprintln(stderr, "详情见 credit -h")
68		}
69		file := fs.String("f", "", "记录文件路径（必需）")
70		if err := fs.Parse(args); err != nil {
71			return exitRejected
72		}
73		if strings.TrimSpace(*file) == "" {
74			fmt.Fprintln(stderr, "错误：必须用 -f 指定记录文件")
75			fs.Usage()
76			return exitRejected
77		}
78		rest := fs.Args()
79		if len(rest) == 0 {
80			fmt.Fprintln(stderr, "错误：缺少子命令")
81			fs.Usage()
82			return exitRejected
83		}
84	
85		store, existed, err := credit.Load(*file)
86		if err != nil {
87			fmt.Fprintf(stderr, "错误：%v\n", err)
88			return exitFile
89		}
90	
91		cmd, cmdArgs := rest[0], rest[1:]
92		code, err := dispatch(store, cmd, cmdArgs, stdout)
93		if err != nil {
94			fmt.Fprintf(stderr, "错误：%v\n", err)
95		}
96	
97		// 只有真正发生变更才落盘：只读核对、纯幂等重复、被拒绝而未写入数据的
98		// 请求都不改动文件，也不会为一次查询凭空创建空文件。被拒绝的免修申请
99		// 已写入免修历史（store 标记为已变更），仍会保存。损坏文件在 Load 阶段
100		// 就已返回，绝不会走到这里覆盖原文件。
101		if store.Dirty() {
102			if saveErr := store.Save(*file); saveErr != nil {
103				fmt.Fprintf(stderr, "错误：保存记录文件失败：%v\n", saveErr)
104				return exitFile
105			}
106			if !existed {
107				fmt.Fprintf(stdout, "（记录文件 %s 不存在，已从空记录开始并创建）\n", *file)
108			}
109		}
110		return code
111	}
