324	func cmdShow(s *credit.Store, args []string, out io.Writer) (int, error) {
325		if len(args) != 1 {
326			return exitRejected, errors.New("用法：show <学生>")
327		}
328		student := args[0]
329		if s.Student(student) == nil {
330			return exitRejected, fmt.Errorf("学生 %s 不存在，没有任何记录", student)
331		}
332		fmt.Fprintf(out, "学生 %s\n", student)
333		reqs := s.Requirements(student)
334		if len(reqs) == 0 {
335			fmt.Fprintln(out, "课程要求：（无）")
336		}
337		for _, r := range reqs {
338			c := s.Course(r.CourseID)
339			fmt.Fprintf(out, "要求 %s -> 课程 %s", r.ID, r.CourseID)
340			if c != nil {
341				fmt.Fprintf(out, "《%s》%d 学分", c.Name, c.Credit)
342			}
343			fmt.Fprintln(out)
344		}
345		enrs := s.Enrollments(student)
346		if len(enrs) == 0 {
347			fmt.Fprintln(out, "修读：（无）")
348		}
349		for _, e := range enrs {
350			fmt.Fprintf(out, "修读 %s：要求 %s，学期 %s，结果：%s\n",
351				e.ID, e.ReqID, e.Term, zhText(e.Result))
352		}
353		ws := s.Waivers(student)
354		if len(ws) == 0 {
355			fmt.Fprintln(out, "免修历史：（无）")
356		}
357		for _, w := range ws {
358			line := fmt.Sprintf("免修 %s：要求 %s，依据 %q，状态：%s",
359				w.ID, w.ReqID, w.Basis, waiverText(w.Status))
360			if w.Reason != "" {
361				line += "（" + w.Reason + "）"
362			}
363			fmt.Fprintln(out, line)
364		}
365		return exitOK, nil
366	}
