895			st.Source != "enrollment" || st.PassedEnrollmentID != "e2" {
896			t.Fatalf("重新打开后来源应仍为先提交通过的 e2，得到学分=%d %+v", rep.TotalCredits, st)
897		}
898		if len(rep.RevokedWaivers) != 1 || rep.RevokedWaivers[0] != "w1" {
899			t.Fatalf("重新打开后已撤销免修应仍列出，得到 %v", rep.RevokedWaivers)
900		}
901		assertTwoPassesIntact(t, loaded)
902		assertRevokedWaiverKept(t, loaded, "获奖材料无法核实")
