		"尾部拼接数组":      `{"version":1}` + `[]`,
		"尾部拼接数字":      `{"version":1} 42`,
		"尾部普通文字":      `{"version":1}` + "普通文字",
		"尾部未写完的对象片段":  `{"version":1} {"version":`,
		"尾部未写完的数组片段":  `{"version":1} [1, 2,`,
		"第二段JSON本身合法也拒绝": `{"version":1,"students":[{"id":"s1"}]}` +
			`{"version":1,"students":[{"id":"s2"}]}`,
	}
	for name, content := range cases {
		t.Run(name, func(t *testing.T) {
			path := filepath.Join(t.TempDir(), "records.json")
			if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
				t.Fatal(err)
			}
			s, existed, err := Load(path)
			if err == nil {
				t.Fatalf("%s：损坏文件应报错，得到 store=%v", name, s)
			}
			if !existed {
				t.Fatalf("%s：损坏文件应标记为已存在", name)
			}
			if !strings.Contains(err.Error(), "内容损坏") ||
				!strings.Contains(err.Error(), "完整记录") {
				t.Fatalf("%s：错误信息应说明内容损坏且完整记录之后有多余内容，得到：%v", name, err)
			}
			got, readErr := os.ReadFile(path)
			if readErr != nil {
				t.Fatal(readErr)
			}
			if string(got) != content {
				t.Fatalf("%s：Load 不得改写损坏文件", name)
			}
		})
	}

	// 无法读取（无权限）时也应报错。
	path := filepath.Join(dir, "noread.json")
	if err := os.WriteFile(path, []byte(`{"version":1}`+"\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(path, 0o000); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.Chmod(path, 0o600) })
	if _, _, err := Load(path); err == nil {
		// root 用户可绕过权限；测试环境若以 root 运行则此断言不适用。
		if os.Getuid() != 0 {
			t.Fatal("不可读文件应报错")
		}
	}
}

